steps.code:
# Let's start by unfriending the users whose emails are in emails_to_unfriend.
# We'll need to search for each user by email and then remove them as a friend.

for email in emails_to_unfriend:
    # Search for the user by email
    search_results = apis.venmo.search_users(access_token=venmo_access_token, query=email, page_index=0, page_limit=1)
    if search_results:
        user_id = search_results[0].get("user_id")
        if user_id:
            apis.venmo.remove_friend(access_token=venmo_access_token, user_id=user_id)

# Now, let's befriend the users whose emails are in emails_to_befriend.
# For each, search by email and add as friend if found.

for email in emails_to_befriend:
    search_results = apis.venmo.search_users(access_token=venmo_access_token, query=email, page_index=0, page_limit=1)
    if search_results:
        user_id = search_results[0].get("user_id")
        if user_id:
            apis.venmo.add_friend(access_token=venmo_access_token, user_id=user_id)

