    for user in results:
        if user.get("email") == email:
            users_to_add[email] = user
            break

print(users_to_add)

# Let's add each of these users as friends on Venmo using their email addresses.
for email, user in users_to_add.items():
    apis.venmo.add_friend(access_token=venmo_access_token, email=email)

# Now, let's proceed to remove the friends who are not in the phone contacts.
for email in to_remove_emails:
    apis.venmo.remove_friend(access_token=venmo_access_token, email=email)

