# For each song in old_songs, let's search Spotify for the song using the title and artist(s) to get its song_id.
# We'll build a mapping from (title, tuple(artists)) to song_id for later use.

old_song_ids = {}

for song in old_songs:
    # We'll use the first artist for the query to maximize match likelihood.
    query = f"{song['title']} {song['artists'][0]}"
    search_results = apis.spotify.search_songs(query=query, page_limit=5)
    # Try to find a result with matching title and at least one matching artist.
    found_id = None
    for result in search_results:
        if result["title"].strip().lower() == song["title"].strip().lower():
            result_artists = [a["name"].strip().lower() for a in result["artists"]]
            if any(artist.strip().lower() in result_artists for artist in song["artists"]):
                found_id = result["song_id"]
                break
    if found_id:
        old_song_ids[(song["title"], tuple(song["artists"]))] = found_id

print(old_song_ids)

